import{_ as n,l as o,o as e,c as l,v as t,p as s,x as r,d as E,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"公募量化与指增","description":"","frontmatter":{"title":"公募量化与指增","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-public-quant.md","filePath":"quant/cn-public-quant.md","lastUpdated":1789023840000}'),u={name:"quant/cn-public-quant.md"};function h(c,a,A,m,_,B){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="公募量化与指增" tabindex="-1">公募量化与指增 <a class="header-anchor" href="#公募量化与指增" aria-label="Permalink to &quot;公募量化与指增&quot;">​</a></h1><div class="epigraph"><p>指数增强把跟踪误差写成约束，把相对基准的超额写成目标。A 股公募还要叠持仓披露、集中度、流动性与对冲工具短缺；超额不是无约束多空。</p><footer>—— 对照 Cremers and Petajisto, How Active is Your Fund Manager?, RFS, 2009 对主动份额与跟踪的讨论；《公开募集证券投资基金运作管理办法》对指数基金与持仓的约束；中证、沪深指数编制方案</footer></div><p><a href="/quant/live-capacity-estimate">上一课</a>把工程课序收在实盘容量。本课打开课程「中国市场进阶」。缺口是<strong>产品形态</strong>：公募量化与指数增强如何把容量、<a href="/quant/index-constituents-history">成分历史</a>与 A 股制度写成可销售的跟踪误差。Cremers 与 Petajisto（2009）把主动份额与跟踪误差拆开；中国公募的主动份额还受披露与风格披露约束。后课私募中性换杠杆与空头工具。不要重写<a href="/quant/lob-structure">LOB</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无约束量化可以做多空、高换手、行业偏离。公募指增的契约通常是：相对沪深 300 / 中证 500 / 中证 1000 等基准的跟踪误差上限、信息比率、以及《运作办法》下的股票仓位、集中度、同业存单与衍生品使用限制。超额必须来自权重偏离，而偏离受成分、涨跌停、停牌与流动性限制。问题是把目标写成：在跟踪误差预算 \\(\\mathrm{TE}^2=(w-w_b)^\\top \\Sigma (w-w_b)\\) 下最大化预期超额，且 \\(w\\) 落在当日可交易集合——不是最大化纸面 IC。</p><p>披露：公募定期报告持仓，使拥挤可被跟踪；量化模型若依赖「隐匿持仓」，与产品类型不符。指数编制与调仓日是基准的一部分，增强必须处理公告–生效窗口的被动冲击，否则超额只是没付的调仓成本。ETF 联接、增强与主动量化的费用与换手不同，夏普不可横比。</p><h3 id="对冲不是公募指增的默认腿" tabindex="-1">对冲不是公募指增的默认腿 <a class="header-anchor" href="#对冲不是公募指增的默认腿" aria-label="Permalink to &quot;对冲不是公募指增的默认腿&quot;">​</a></h3><p>公募可以使用股指期货等衍生品做替代持仓或对冲，但仓位、套保目的与估值要符合基金合同与法规。把指增写成「现货多头 + 期货空头的市场中性」，通常是私募结构，见下一课。指增的 beta 应对着基准，而不是对着现金。贴水与保证金若进入公募，须进费用与跟踪误差，而不是当免费杠杆。</p><p><span class="marginnote">基准必须是点-in-time 官方成分与权重。用当前 300 成分回测十年增强，存活偏差与调仓冲击都会变成假超额。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>优化器输入：基准权重 \\(w_b\\)、预测、风险模型、交易成本、涨跌停与停牌掩码、<a href="/quant/cn-tplus1">T+1</a> 可卖量。输出偏离受 TE、行业、个股权重上限约束。调仓日单独情景：被动基金与 ETF 的冲击下，增强选择跟随、提前或避开，须在研究日志登记，不能事后挑。容量用上一课方法：先碰到的往往是小盘基准里的涨跌停与参与率，不是大盘 ADV。</p><p>评价：超额、TE、IR、最大偏离行业、换手、费用后对投资者的净超额。主动份额与 TE 同时报告，避免「高换手但其实在复制基准」或「低 TE 但大量场外暴露」。与美股指增对照时声明：A 股涨跌停使 TE 在板子日跳升，这是制度方差，不是模型突然变差。</p><h3 id="量化公募的因子要过制度过滤" tabindex="-1">量化公募的因子要过制度过滤 <a class="header-anchor" href="#量化公募的因子要过制度过滤" aria-label="Permalink to &quot;量化公募的因子要过制度过滤&quot;">​</a></h3><p>换手、小盘、反转在 A 股文献里显著，见<a href="/quant/cn-turnover-factor">换手因子</a>与 Liu–Stambaugh–Yuan。公募实现必须扣：不可当日纠错、披露后的拥挤、以及不可空的一端变成低配而非空头。纸面多空 IC 不能当指增预期超额。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>跟踪误差预算把因子暴露变成相对基准的倾斜。A 股流动性与涨跌停使倾斜的实现路径不对称：涨停买不进调入股，跌停卖不出调出股，TE 与超额在同一天被制度改写。公募持仓披露缩短隐匿期，容量比同等私募更紧。这是产品设计，不是 alpha 失效。</p><p>指数增强的「增强」来自可交易偏离；偏离的可交易性由微观结构决定。工程课的容量曲线在这里变成合同里的规模上限。</p>',17)),(e(),s(p,null,{default:r(()=>[d(i,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20Bench%5B%22%E7%82%B9-in-time%20%E5%9F%BA%E5%87%86%22%5D%20--%3E%20TE%5B%22%E8%B7%9F%E8%B8%AA%E8%AF%AF%E5%B7%AE%E9%A2%84%E7%AE%97%22%5D%0A%20%20Pred%5B%22%E6%88%AA%E9%9D%A2%E9%A2%84%E6%B5%8B%22%5D%20--%3E%20Opt%5B%22%E7%BA%A6%E6%9D%9F%E4%BC%98%E5%8C%96%22%5D%0A%20%20Mask%5B%22%E6%B6%A8%E8%B7%8C%E5%81%9C%20%E5%81%9C%E7%89%8C%20T%2B1%22%5D%20--%3E%20Opt%0A%20%20TE%20--%3E%20Opt%0A%20%20Opt%20--%3E%20W%5B%22%E5%8F%AF%E4%BA%A4%E6%98%93%E5%81%8F%E7%A6%BB%22%5D%0A%20%20Disc%5B%22%E5%AE%9A%E6%9C%9F%E6%8A%AB%E9%9C%B2%22%5D%20--%3E%20Crowd%5B%22%E6%8B%A5%E6%8C%A4%E6%8A%98%E5%87%8F%E5%AE%B9%E9%87%8F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供规避持仓披露、用场外收益互换把杠杆移出报表的产品设计。基金分类与宣传以证监会与协会规则为准。本课不评价具体基金业绩。量化监管演进在后课专写，本课只把公募契约当约束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指增是 TE 约束下的可交易偏离，不是无约束多空。</li><li>基准与披露必须点-in-time；调仓窗口单独记账。</li><li>容量先满在涨跌停、小盘参与率与披露拥挤。</li><li>出处：Cremers and Petajisto, <em>RFS</em>, 2009；《公开募集证券投资基金运作管理办法》；指数编制方案。</li></ul>',4))])}const b=n(u,[["render",h]]);export{q as __pageData,b as default};
